1	/* ============================================================
2	   CAREERS HERO — careers-hero.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: transparent;
7	  padding: 4rem 5% 3rem;
8	  overflow: hidden;
9	}
10	
11	.container {
12	  width: 100%;
13	  max-width: 1280px;
14	  margin-left: auto;
15	  margin-right: auto;
16	}
17	
18	/* Content block */
19	.content {
20	  text-align: center;
21	  max-width: 760px;
22	  margin-left: auto;
23	  margin-right: auto;
24	  padding-bottom: 56px;
25	}
26	
27	/* Badge (.careersubott) */
28	.badge {
29	  color: #05bafe;
30	  background-color: #21cfff12;
31	  border: 1px solid #05bafe;
32	  border-radius: 20px;
33	  margin-bottom: 17px;
34	  padding: 0 13px;
35	  line-height: 14px;
36	  display: inline-flex;
37	  align-items: center;
38	}
39	
40	.badgeText {
41	  font-family: 'Roobert PRO', Arial, sans-serif;
42	  font-size: 12px;
43	  font-weight: 700;
44	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
45	  -webkit-background-clip: text;
46	  -webkit-text-fill-color: transparent;
47	  background-clip: text;
48	  padding-top: 6px;
49	  padding-bottom: 6px;
50	  margin: 0;
51	}
52	
53	/* Heading (.career-ban-title) */
54	.heading {
55	  color: #092245;
56	  margin-top: 0;
57	  padding: 0;
58	  font-family: 'Roobert PRO', Arial, sans-serif;
59	  font-size: 40px;
60	  font-weight: 700;
61	  line-height: 1.25;
62	  text-decoration: none;
63	  margin-bottom: 10px;
64	}
65	
66	/* Subtitle (.h1-season-seeing.web-h1) */
67	.subtitle {
68	  color: #2b2b2b;
69	  max-width: 53rem;
70	  margin-left: auto;
71	  margin-right: auto;
72	  margin-top: 0;
73	  padding-left: 1.5rem;
74	  padding-right: 1.5rem;
75	  font-family: 'Roobert PRO', Arial, sans-serif;
76	  font-size: 16px;
77	  font-weight: 400;
78	  line-height: 28px;
79	  margin-bottom: 40px;
80	}
81	
82	/* CTA row */
83	.ctaRow {
84	  display: flex;
85	  align-items: center;
86	  justify-content: center;
87	}
88	
89	/* CTA button (.a-gulf-book) */
90	.ctaButton {
91	  color: #fff;
92	  width: auto;
93	  font-family: 'Roobert PRO', Arial, sans-serif;
94	  font-size: 1rem;
95	  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
96	  background-position: 93%, 0 0;
97	  background-repeat: no-repeat, repeat;
98	  background-size: auto, auto;
99	  border: 2px solid transparent;
100	  border-radius: 0.75rem;
101	  justify-content: center;
102	  align-items: center;
103	  padding: 0.75rem 3rem 0.75rem 1.25rem;
104	  font-weight: 700;
105	  line-height: 1.75rem;
106	  text-decoration: none;
107	  display: inline-flex;
108	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
109	}
110	
111	.ctaButton:hover {
112	  background-color: #092245;
113	  background-image: url('/images/webflow/Group-46729-2.svg');
114	  background-repeat: no-repeat;
115	  background-size: auto;
116	}
117	
118	/* Gallery row */
119	.galleryRow {
120	  display: grid;
121	  grid-template-columns: 1fr 1fr 1fr;
122	  gap: 16px;
123	  align-items: flex-end;
124	}
125	
126	.galleryCard {
127	  position: relative;
128	  border-radius: 16px 16px 0 0;
129	  overflow: hidden;
130	  height: 280px;
131	}
132	
133	/* Subtle stagger/offset per card */
134	.galleryCard1 {
135	  transform: translateY(8px);
136	  height: 260px;
137	}
138	
139	.galleryCard2 {
140	  height: 300px;
141	}
142	
143	.galleryCard3 {
144	  transform: translateY(12px);
145	  height: 250px;
146	}
147	
148	.galleryImage {
149	  object-fit: cover;
150	  object-position: center top;
151	  transition: transform 0.4s ease;
152	}
153	
154	.galleryCard:hover .galleryImage {
155	  transform: scale(1.04);
156	}
157	
158	/* ============================================================
159	   max-width: 991px
160	   ============================================================ */
161	@media screen and (max-width: 991px) {
162	  .section {
163	    padding: 60px 5% 0;
164	  }
165	
166	  .galleryRow {
167	    gap: 12px;
168	  }
169	
170	  .galleryCard {
171	    height: 220px;
172	  }
173	
174	  .galleryCard1 {
175	    height: 200px;
176	  }
177	
178	  .galleryCard2 {
179	    height: 240px;
180	  }
181	
182	  .galleryCard3 {
183	    height: 190px;
184	  }
185	}
186	
187	/* ============================================================
188	   max-width: 767px
189	   ============================================================ */
190	@media screen and (max-width: 767px) {
191	  .section {
192	    padding: 56px 5% 0;
193	  }
194	
195	  .content {
196	    padding-bottom: 40px;
197	  }
198	
199	  .galleryRow {
200	    grid-template-columns: 1fr 1fr;
201	    gap: 10px;
202	  }
203	
204	  .galleryCard3 {
205	    display: none;
206	  }
207	
208	  .galleryCard1,
209	  .galleryCard2 {
210	    transform: none;
211	    height: 200px;
212	    border-radius: 12px 12px 0 0;
213	  }
214	}
215	
216	/* ============================================================
217	   max-width: 479px  (mobile)
218	   ============================================================ */
219	@media screen and (max-width: 479px) {
220	  .section {
221	    padding: 48px 1.25rem 0;
222	  }
223	
224	  .heading {
225	    font-size: 1.9rem;
226	    line-height: 1.25;
227	  }
228	
229	  .subtitle {
230	    font-size: 1rem;
231	    padding-left: 0;
232	    padding-right: 0;
233	  }
234	
235	  .ctaButton {
236	    width: 100%;
237	    justify-content: center;
238	  }
239	
240	  .galleryRow {
241	    grid-template-columns: 1fr;
242	    max-width: 360px;
243	    margin-left: auto;
244	    margin-right: auto;
245	  }
246	
247	  .galleryCard1 {
248	    display: none;
249	  }
250	
251	  .galleryCard2 {
252	    height: 220px;
253	    border-radius: 12px 12px 0 0;
254	  }
255	
256	  .galleryCard3 {
257	    display: none;
258	  }
259	}
