1	/* ============================================================
2	   CAREERS TABS — careers-tabs.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: #f5f7fa;
7	  padding: 80px 5% 88px;
8	}
9	
10	.container {
11	  width: 100%;
12	  max-width: 1280px;
13	  margin-left: auto;
14	  margin-right: auto;
15	}
16	
17	/* Section header */
18	.header {
19	  text-align: center;
20	  max-width: 680px;
21	  margin-left: auto;
22	  margin-right: auto;
23	  margin-bottom: 48px;
24	}
25	
26	.heading {
27	  color: #092245;
28	  font-family: 'Roobert PRO', Arial, sans-serif;
29	  font-size: 40px;
30	  font-weight: 700;
31	  line-height: 1.2;
32	  margin-bottom: 16px;
33	}
34	
35	.subtitle {
36	  color: #2b2b2b;
37	  font-family: 'Roobert PRO', Arial, sans-serif;
38	  font-size: 16px;
39	  font-weight: 400;
40	  line-height: 28px;
41	  margin: 0;
42	}
43	
44	/* Tab navigation */
45	.tabNav {
46	  display: flex;
47	  align-items: center;
48	  justify-content: center;
49	  gap: 0;
50	  border-bottom: 1px solid #e5e7eb;
51	  margin-bottom: 52px;
52	  overflow-x: auto;
53	  -webkit-overflow-scrolling: touch;
54	  scrollbar-width: none;
55	}
56	
57	.tabNav::-webkit-scrollbar {
58	  display: none;
59	}
60	
61	.tabButton {
62	  position: relative;
63	  flex-shrink: 0;
64	  background: none;
65	  border: none;
66	  border-bottom: 2px solid transparent;
67	  padding: 14px 24px;
68	  margin-bottom: -1px;
69	  color: #6b7280;
70	  font-family: 'Roobert PRO', Arial, sans-serif;
71	  font-size: 15px;
72	  font-weight: 500;
73	  line-height: 1.4;
74	  cursor: pointer;
75	  transition: color 0.2s;
76	  white-space: nowrap;
77	}
78	
79	.tabButton:hover {
80	  color: #092245;
81	}
82	
83	.tabButtonActive {
84	  color: #092245;
85	  font-weight: 700;
86	  border-bottom: 2px solid transparent;
87	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
88	  background-size: 100% 2px;
89	  background-repeat: no-repeat;
90	  background-position: bottom center;
91	}
92	
93	/* Tab content area */
94	.tabContent {
95	  min-height: 400px;
96	}
97	
98	.tabPane {
99	  animation: fadeTabIn 0.22s ease-out;
100	}
101	
102	@keyframes fadeTabIn {
103	  from {
104	    opacity: 0;
105	    transform: translateY(6px);
106	  }
107	  to {
108	    opacity: 1;
109	    transform: translateY(0);
110	  }
111	}
112	
113	/* Two-column layout (About + Culture tabs) */
114	.twoColLayout {
115	  display: grid;
116	  grid-template-columns: 1fr 1fr;
117	  gap: 64px;
118	  align-items: center;
119	}
120	
121	.twoColReverse {
122	  /* Culture tab: text left, images right */
123	}
124	
125	/* Image stack */
126	.imageStack {
127	  display: flex;
128	  flex-direction: column;
129	  gap: 16px;
130	}
131	
132	.imageWrapper {
133	  position: relative;
134	  border-radius: 16px;
135	  overflow: hidden;
136	  height: 220px;
137	}
138	
139	.imageWrapperSecond {
140	  height: 180px;
141	  margin-left: 32px;
142	}
143	
144	.stackImage {
145	  object-fit: cover;
146	  object-position: center;
147	}
148	
149	/* Text column */
150	.textColumn {
151	  display: flex;
152	  flex-direction: column;
153	  gap: 0;
154	}
155	
156	.tabHeading {
157	  color: #092245;
158	  font-family: 'Roobert PRO', Arial, sans-serif;
159	  font-size: 32px;
160	  font-weight: 700;
161	  line-height: 1.2;
162	  margin-bottom: 20px;
163	}
164	
165	.tabParagraph {
166	  color: #2b2b2b;
167	  font-family: 'Roobert PRO', Arial, sans-serif;
168	  font-size: 16px;
169	  font-weight: 400;
170	  line-height: 28px;
171	  margin-bottom: 16px;
172	}
173	
174	.tabCta {
175	  display: inline-flex;
176	  align-items: center;
177	  justify-content: center;
178	  color: #fff;
179	  font-family: 'Roobert PRO', Arial, sans-serif;
180	  font-size: 0.9375rem;
181	  font-weight: 700;
182	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
183	  border-radius: 0.75rem;
184	  padding: 0.7rem 1.5rem;
185	  text-decoration: none;
186	  margin-top: 8px;
187	  transition: filter 0.2s, box-shadow 0.2s;
188	  align-self: flex-start;
189	}
190	
191	.tabCta:hover {
192	  filter: brightness(1.1);
193	  box-shadow: 0 4px 20px rgba(33, 207, 255, 0.3);
194	}
195	
196	/* Benefits tab */
197	.benefitsHeader {
198	  text-align: center;
199	  max-width: 640px;
200	  margin-left: auto;
201	  margin-right: auto;
202	  margin-bottom: 40px;
203	}
204	
205	.tabSubtitleCenter {
206	  color: #2b2b2b;
207	  font-family: 'Roobert PRO', Arial, sans-serif;
208	  font-size: 16px;
209	  font-weight: 400;
210	  line-height: 28px;
211	  margin: 0;
212	}
213	
214	.benefitsGrid {
215	  display: grid;
216	  grid-template-columns: repeat(4, 1fr);
217	  gap: 24px;
218	}
219	
220	.benefitCard {
221	  background-color: #fff;
222	  border: 1px solid #e5e7eb;
223	  border-radius: 16px;
224	  padding: 32px 28px;
225	  transition: background-color 0.3s, border-color 0.4s, box-shadow 0.3s;
226	}
227	
228	.benefitCard:hover {
229	  background-color: #cdebfa;
230	  border-color: #009ce0;
231	  box-shadow: 0 4px 20px rgba(1, 154, 230, 0.1);
232	}
233	
234	.benefitIcon {
235	  display: block;
236	  margin-bottom: 20px;
237	}
238	
239	.benefitTitle {
240	  color: #092245;
241	  font-family: 'Roobert PRO', Arial, sans-serif;
242	  font-size: 18px;
243	  font-weight: 700;
244	  line-height: 1.3;
245	  margin-bottom: 12px;
246	}
247	
248	.benefitText {
249	  color: #4b5563;
250	  font-family: 'Roobert PRO', Arial, sans-serif;
251	  font-size: 15px;
252	  font-weight: 400;
253	  line-height: 26px;
254	  margin: 0;
255	}
256	
257	/* Career Opportunities tab */
258	.opportunitiesHeader {
259	  text-align: center;
260	  max-width: 640px;
261	  margin-left: auto;
262	  margin-right: auto;
263	  margin-bottom: 40px;
264	}
265	
266	.jobList {
267	  display: flex;
268	  flex-direction: column;
269	  gap: 0;
270	  border: 1px solid #e5e7eb;
271	  border-radius: 16px;
272	  overflow: hidden;
273	  background: #fff;
274	}
275	
276	.jobItem {
277	  border-bottom: 1px solid #e5e7eb;
278	}
279	
280	.jobItem:last-child {
281	  border-bottom: none;
282	}
283	
284	.jobToggle {
285	  width: 100%;
286	  background: none;
287	  border: none;
288	  padding: 24px 28px;
289	  cursor: pointer;
290	  text-align: left;
291	  transition: background-color 0.2s;
292	}
293	
294	.jobToggle:hover {
295	  background-color: #f9fafb;
296	}
297	
298	.jobTitleRow {
299	  display: flex;
300	  align-items: center;
301	  justify-content: space-between;
302	  gap: 16px;
303	}
304	
305	.jobMeta {
306	  flex: 1;
307	  min-width: 0;
308	}
309	
310	.jobTitle {
311	  color: #092245;
312	  font-family: 'Roobert PRO', Arial, sans-serif;
313	  font-size: 17px;
314	  font-weight: 700;
315	  line-height: 1.3;
316	  margin: 0 0 4px;
317	}
318	
319	.jobType {
320	  color: #6b7280;
321	  font-family: 'Roobert PRO', Arial, sans-serif;
322	  font-size: 13px;
323	  font-weight: 400;
324	  margin: 0;
325	}
326	
327	.jobArrow {
328	  flex-shrink: 0;
329	  transition: transform 0.22s ease;
330	}
331	
332	.jobArrowOpen {
333	  transform: rotate(180deg);
334	}
335	
336	.jobContent {
337	  padding: 0 28px 28px;
338	  border-top: 1px solid #f3f4f6;
339	}
340	
341	.jobDescription {
342	  color: #2b2b2b;
343	  font-family: 'Roobert PRO', Arial, sans-serif;
344	  font-size: 15px;
345	  font-weight: 400;
346	  line-height: 26px;
347	  margin: 20px 0 24px;
348	}
349	
350	.jobColumns {
351	  display: grid;
352	  grid-template-columns: 1fr 1fr;
353	  gap: 32px;
354	}
355	
356	.jobSectionLabel {
357	  color: #092245;
358	  font-family: 'Roobert PRO', Arial, sans-serif;
359	  font-size: 13px;
360	  font-weight: 700;
361	  text-transform: uppercase;
362	  letter-spacing: 0.06em;
363	  margin-bottom: 12px;
364	}
365	
366	.jobListItem {
367	  color: #4b5563;
368	  font-family: 'Roobert PRO', Arial, sans-serif;
369	  font-size: 14px;
370	  font-weight: 400;
371	  line-height: 1.6;
372	  margin-bottom: 8px;
373	  padding-left: 4px;
374	}
375	
376	.fallbackNote {
377	  text-align: center;
378	  color: #6b7280;
379	  font-family: 'Roobert PRO', Arial, sans-serif;
380	  font-size: 15px;
381	  font-weight: 400;
382	  margin-top: 32px;
383	}
384	
385	.fallbackLink {
386	  color: #019ae6;
387	  text-decoration: underline;
388	  font-weight: 600;
389	}
390	
391	.fallbackLink:hover {
392	  color: #21cfff;
393	}
394	
395	/* ============================================================
396	   max-width: 1199px
397	   ============================================================ */
398	@media screen and (max-width: 1199px) {
399	  .benefitsGrid {
400	    grid-template-columns: repeat(2, 1fr);
401	  }
402	}
403	
404	/* ============================================================
405	   max-width: 991px
406	   ============================================================ */
407	@media screen and (max-width: 991px) {
408	  .section {
409	    padding: 56px 5% 64px;
410	  }
411	
412	  .heading {
413	    font-size: 34px;
414	  }
415	
416	  .twoColLayout {
417	    grid-template-columns: 1fr;
418	    gap: 40px;
419	  }
420	
421	  .twoColReverse .imageStack {
422	    order: -1;
423	  }
424	
425	  .imageWrapper {
426	    height: 260px;
427	  }
428	
429	  .imageWrapperSecond {
430	    height: 200px;
431	    margin-left: 20px;
432	  }
433	
434	  .tabButton {
435	    padding: 12px 18px;
436	    font-size: 14px;
437	  }
438	}
439	
440	/* ============================================================
441	   max-width: 767px
442	   ============================================================ */
443	@media screen and (max-width: 767px) {
444	  .heading {
445	    font-size: 28px;
446	    line-height: 1.25;
447	  }
448	
449	  .header {
450	    margin-bottom: 36px;
451	  }
452	
453	  .tabNav {
454	    justify-content: flex-start;
455	  }
456	
457	  .benefitsGrid {
458	    grid-template-columns: 1fr;
459	    max-width: 520px;
460	    margin-left: auto;
461	    margin-right: auto;
462	  }
463	
464	  .jobColumns {
465	    grid-template-columns: 1fr;
466	    gap: 20px;
467	  }
468	
469	  .jobToggle {
470	    padding: 20px;
471	  }
472	
473	  .jobContent {
474	    padding: 0 20px 24px;
475	  }
476	
477	  .tabHeading {
478	    font-size: 26px;
479	  }
480	}
481	
482	/* ============================================================
483	   max-width: 479px  (mobile)
484	   ============================================================ */
485	@media screen and (max-width: 479px) {
486	  .section {
487	    padding: 48px 1.25rem 56px;
488	  }
489	
490	  .heading {
491	    font-size: 1.5rem;
492	  }
493	
494	  .subtitle {
495	    font-size: 0.9375rem;
496	  }
497	
498	  .tabButton {
499	    padding: 10px 14px;
500	    font-size: 13px;
501	  }
502	
503	  .tabCta {
504	    width: 100%;
505	    justify-content: center;
506	    align-self: auto;
507	  }
508	
509	  .benefitCard {
510	    padding: 24px 20px;
511	  }
512	
513	  .imageWrapperSecond {
514	    margin-left: 0;
515	  }
516	}
