1	/* ============================================================
2	   CAREERS SELECTION — careers-selection.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: #fff;
7	  padding: 80px 5% 88px;
8	}
9	
10	.container {
11	  width: 100%;
12	  max-width: 1280px;
13	  margin-left: auto;
14	  margin-right: auto;
15	}
16	
17	/* Header */
18	.header {
19	  text-align: center;
20	  max-width: 680px;
21	  margin-left: auto;
22	  margin-right: auto;
23	  margin-bottom: 52px;
24	}
25	
26	.heading {
27	  color: #092245;
28	  font-family: 'Roobert PRO', Arial, sans-serif;
29	  font-size: 40px;
30	  font-weight: 700;
31	  line-height: 1.2;
32	  margin-bottom: 16px;
33	}
34	
35	.subtitle {
36	  color: #2b2b2b;
37	  font-family: 'Roobert PRO', Arial, sans-serif;
38	  font-size: 16px;
39	  font-weight: 400;
40	  line-height: 28px;
41	  margin: 0;
42	}
43	
44	/* Cards grid — 4 columns */
45	.grid {
46	  display: grid;
47	  grid-column-gap: 24px;
48	  grid-row-gap: 24px;
49	  grid-template-rows: auto;
50	  grid-template-columns: repeat(4, 1fr);
51	}
52	
53	.card {
54	  background-color: #f5f7fa;
55	  border: 1px solid #e5e7eb;
56	  border-radius: 16px;
57	  padding: 32px 28px;
58	  transition: background-color 0.3s, border-color 0.4s, box-shadow 0.3s;
